package cn.zhuatech.esign;
import org.junit.jupiter.api.Test;import org.springframework.beans.factory.annotation.Autowired;import org.springframework.boot.test.context.SpringBootTest;import org.springframework.boot.webmvc.test.autoconfigure.AutoConfigureMockMvc;import org.springframework.http.MediaType;import org.springframework.test.web.servlet.MockMvc;import static org.springframework.security.test.web.servlet.request.SecurityMockMvcRequestPostProcessors.httpBasic;import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.post;import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*;
@SpringBootTest @AutoConfigureMockMvc class EnterpriseEvidenceApiTests {@Autowired MockMvc mvc;private static final String HASH="aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa";
 @Test void completeEvidenceBuildsDeterministicManifest() throws Exception {mvc.perform(post("/api/enterprise/esign/evidence-manifest").with(httpBasic("operator","operator123")).contentType(MediaType.APPLICATION_JSON).content("{\"envelopeNo\":\"ENV-1\",\"documentSha256\":\""+HASH+"\",\"trustedTimestamp\":\"2026-08-26T12:00:00+08:00\",\"signers\":[{\"signerId\":\"U1\",\"signerName\":\"张三\",\"identityVerified\":true,\"sealAuthorized\":true,\"signedAt\":\"2026-08-26T11:00:00+08:00\",\"clientIp\":\"127.0.0.1\",\"signatureSha256\":\""+HASH+"\"}]}")).andExpect(status().isOk()).andExpect(jsonPath("$.data.manifestSha256").isString()).andExpect(jsonPath("$.data.decision").value("ARCHIVE_READY"));}
 @Test void missingTrustEvidenceIsReported() throws Exception {mvc.perform(post("/api/enterprise/esign/evidence-manifest").with(httpBasic("operator","operator123")).contentType(MediaType.APPLICATION_JSON).content("{\"envelopeNo\":\"ENV-2\",\"documentSha256\":\""+HASH+"\",\"signers\":[{\"signerId\":\"U1\",\"signerName\":\"张三\",\"identityVerified\":false,\"sealAuthorized\":false,\"clientIp\":\"127.0.0.1\",\"signatureSha256\":\""+HASH+"\"}]}")).andExpect(status().isOk()).andExpect(jsonPath("$.data.decision").value("EVIDENCE_INCOMPLETE")).andExpect(jsonPath("$.data.missingEvidence.length()").value(4));}
}
